// Only the accept loop is nonblocking; HTTP handlers require blocking socket I/O.
fn main()->Result<(),Box<dyn std::error::Error>>{
 use std::io::{Read,Write};use std::sync::{Arc,atomic::{AtomicBool,AtomicUsize,Ordering}};
 let args=std::env::args().skip(1).collect::<Vec<_>>();let states=args[0].split(',').map(str::to_owned).collect::<Vec<_>>();let retries=args[1].parse::<u32>()?;let timeout=args[2].parse::<u64>()?;
 let listener=std::net::TcpListener::bind("127.0.0.1:0")?;listener.set_nonblocking(true)?;let url=format!("http://{}/source",listener.local_addr()?);
 let stop=Arc::new(AtomicBool::new(false));let count=Arc::new(AtomicUsize::new(0));let worker_stop=stop.clone();let worker_count=count.clone();
 let server=std::thread::spawn(move||{let mut handlers=Vec::new();while !worker_stop.load(Ordering::SeqCst){match listener.accept(){Ok((mut stream,_))=>{let index=worker_count.fetch_add(1,Ordering::SeqCst);let state=states.get(index).unwrap_or_else(||states.last().unwrap()).clone();handlers.push(std::thread::spawn(move||->std::io::Result<()>{stream.set_nonblocking(false)?;stream.set_read_timeout(Some(std::time::Duration::from_secs(10)))?;let mut request=Vec::new();let mut b=[0];while !request.ends_with(b"\r\n\r\n"){if request.len()>32768{return Err(std::io::Error::other("header too long"));}stream.read_exact(&mut b)?;request.push(b[0]);}
 if state=="delay"{std::thread::sleep(std::time::Duration::from_millis(6000));}let status=state.parse::<u16>().unwrap_or(200);let body=if status==200{b"body".as_slice()}else{b"".as_slice()};let length=if state=="truncate"{14}else{body.len()};write!(stream,"HTTP/1.1 {status} test\r\nContent-Length: {length}\r\nConnection: close\r\n\r\n")?;stream.write_all(body)?;Ok(())}));},Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>std::thread::sleep(std::time::Duration::from_millis(2)),Err(_)=>break,}}
 handlers.into_iter().map(|h|format!("{:?}",h.join())).collect::<Vec<_>>()});
 let plan=fletch_core::fetch_plan_with_kind("retry-fixture",url,fletch_core::SourceKind::Http)?;let fetched=fletch_core::fetch_to_cache(&plan,fletch_core::FetchOptions::new(&args[3]).with_force(true).with_retry_attempts(retries).with_timeout_ms(timeout).with_fetched_at_ms(0));stop.store(true,Ordering::SeqCst);let server_results=server.join().map_err(|_|"server failed")?;
 let mut output=match fetched{Ok(outcome)=>serde_json::json!({"requests":count.load(Ordering::SeqCst),"attempt_status":outcome.attempt_status,"entry_attempts":outcome.entry.fetch_attempts,"entry_retries":outcome.entry.retry_count}),Err(error)=>serde_json::json!({"requests":count.load(Ordering::SeqCst),"error":error.to_string(),"error_debug":format!("{error:?}")})};output["server_handlers"]=serde_json::json!(server_results);print!("{}",serde_json::to_string(&output)?);Ok(())
}
